async function transporteLocal() {
  return new Response(JSON.stringify([{ nome: "Leitura" }]), { status: 200 });
}
async function carregar() {
  const resposta = await transporteLocal();
  if (!resposta.ok) throw new Error(`HTTP ${resposta.status}`);
  const oficinas = await resposta.json();
  console.log(oficinas[0].nome);
}
carregar().catch(erro => console.error(erro.message));

async function demonstrarFalha() {
  console.log("Carregando");
  try {
    const resposta = new Response(null, { status: 503 });
    if (!resposta.ok) throw new Error("Serviço indisponível");
  } catch (erro) {
    console.error(erro.message);
  } finally {
    console.log("Carregamento encerrado");
  }
}
demonstrarFalha();

